emit <- function(name, value) cat(name, ":", if (isTRUE(value)) "ok" else "FAIL", "\n", sep="")
local({
  con <- textConnection("lines", "w", local=TRUE)
  cat("first\n", file=con)
  emit("complete", identical(lines, "first"))
  before <- lines
  cat("par", file=con)
  emit("partial-binding", identical(lines, "first"))
  emit("partial-value", identical(textConnectionValue(con), "first"))
  gc()
  cat("tial\n", file=con)
  emit("partial-complete", identical(lines, c("first", "partial")))
  emit("previous-value", identical(before, "first"))
  cat("\n\nlast", file=con)
  emit("blank-lines", identical(lines, c("first", "partial", "", "")))
  close(con)
  emit("close-fragment", identical(lines, c("first", "partial", "", "", "last")))
})
local({
  con <- textConnection("lines", "w", local=TRUE)
  writeLines(c("one", "two"), con, sep=":")
  emit("write-lines-partial", identical(textConnectionValue(con), character()))
  close(con)
  emit("write-lines-close", identical(lines, "one:two:"))
})
local({
  con <- textConnection("lines", "w", local=TRUE)
  result <- capture.output({ cat("captured\n") }, file=con)
  emit("capture-return", is.null(result))
  emit("capture-connection-open", isOpen(con))
  close(con)
  emit("capture-lines", identical(lines, "captured"))
})
local({
  first <- textConnection("a", "w", local=TRUE)
  second <- textConnection("b", "w", local=TRUE)
  sink(first)
  cat("first\n")
  sink(second, split=TRUE)
  cat("both\n")
  sink()
  cat("last\n")
  sink()
  close(first)
  close(second)
  emit("split-first", identical(a, c("first", "both", "last")))
  emit("split-second", identical(b, "both"))
})
